	 (2310,'Assassin''s Creed Freedom Cry [Online Game Code]','Assassin''s Creed Freedom Cry','https://store.steampowered.com/app/277590/Assassins_Creed_Freedom_Cry/','Action,Adventure','["Video Games", "PC", "Games", "</span></span></span>"]','["Action,Adventure,Assassin,Open World,Pirates,Stealth,Singleplayer,Parkour,Third Person,Historical,Story Rich,Atmospheric,RPG,Naval,Sailing,Sci-fi,Masterpiece,Great Soundtrack,Swordplay,Gore"]','assassins creed freedom cry'),
	 (2311,'Assassin''s Creed® III Remastered','Assassin''s Creed® III Remastered','https://store.steampowered.com/app/911400/Assassins_Creed_III_Remastered/','Action,Adventure','[]','["Action,Adventure,Assassin,Open World,Historical,Stealth"]','assassins creed iii remastered'),
	 (2312,'Assassin''s Creed IV Black Flag [Online Game Code]','Assassin’s Creed® IV Black Flag™','https://store.steampowered.com/app/242050/Assassins_Creed_IV_Black_Flag/','Action,Adventure','["Video Games", "PC", "</span></span></span>", "A BRASH REBEL ASSASSIN: Become Edward Kenway, a charismatic yet brutal pirate captain, trained by Assassins. Edward can effortlessly switch between the Hidden Blade of the Assassin''s Order and all new weaponry including four flintock pistols and dual cutlass swords.", "EXPLORE AN OPEN WORLD FILLED WITH OPPORTUNITIES: Discover the most diverse Assassin''s Creed world ever created. From Kingston to Nassau, explore 50 unique locations where you can live the life of a pirate.", "BECOME THE MOST FEARED PIRATE IN THE CARIBBEAN: Command your ship, the Jackdaw, and strike fear in all who see her. Plunder and pillage to upgrade the Jackdaw with ammunition and equipment needed to fight off enemy ships.", "EXPERIENCE THE GRITTY REALITY BEHIND THE PIRATE FANTASY: Stand amongst legendary names such as Blackbeard and Benjamin Hornigold, as you establish a lawless Republic in the Bahamas and relive the truly explosive events that defined the Golden Age of Pirates.", "MULTIPLAYER EXPERIENCE: Play with your friends in the ruthless and critically acclaimed multiplayer experience. Choose from an eclectic cast of characters from the Golden Age of Pirates and fight to the death in exotic locations."]','["Pirates,Open World,Assassin,Action,Adventure,Stealth,Third Person,Naval,Parkour,Multiplayer,Historical,Story Rich,Singleplayer,Exploration,Action-Adventure,Atmospheric,RPG,Sandbox,Mature,Action RPG"]','assassins creed iv black flag'),
	 (2313,'Assassin''s Creed IV Black Flag','Assassin’s Creed® IV Black Flag™','https://store.steampowered.com/app/242050/Assassins_Creed_IV_Black_Flag/','Action,Adventure','["Video Games", "Xbox One", "</span></span></span>"]','["Pirates,Open World,Assassin,Action,Adventure,Stealth,Third Person,Naval,Parkour,Multiplayer,Historical,Story Rich,Singleplayer,Exploration,Action-Adventure,Atmospheric,RPG,Sandbox,Mature,Action RPG"]','assassins creed iv black flag'),
