INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (3067,'Batman: Arkham Knight [Online Game Code]','Batman™: Arkham Knight','https://store.steampowered.com/app/208650/Batman_Arkham_Knight/','Action,Adventure','["Video Games", "PC", "</span></span></span>", "The Batmobile: Gamers have demanded it, and Batman: Arkham Knight delivers. The all new Batmobile sits at the heart of the gameplay experience and augments Batman''s abilities in every respect.", "Next-Gen Gotham City: Harnessing the power of the next generation of games systems, the entirety of Gotham City has been created in immense scale and with intimate detail offering players a truly legendary next-gen game world.", "The Epic Conclusion to a Legendary Trilogy: Rocksteady Studios returns to the helm of the multi-award winning franchise. Scarecrow is back to wreak his revenge against Batman joined by a completely new and original character, the Arkham Knight.", "Be The Batman: Batman, the Batmobile, the entirety of Gotham City. Batman: Arkham Knight is the complete and ultimate Batman offering."]','["Batman,Action,Open World,Superhero,Stealth,Adventure,Third Person,Singleplayer,Detective,Fighting,Atmospheric,Story Rich,Dark,Comic Book,Masterpiece,Beat ''em up,Puzzle,Mature,Strategy,Sandbox"]','batman arkham knight'),
