INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (8591,'Deus Ex: Game of the Year Edition [Online Game Code]','Deus Ex: Game of the Year Edition','https://store.steampowered.com/app/6910/Deus_Ex_Game_of_the_Year_Edition/','Action','["Video Games", "PC", "Games", "</span></span></span>", "Real role-playing from an immersive 3D, first-person perspective. Multiple solutions to problems and character development choices ensure a varied game experience. Talk, fight or use skills to get past obstacles as the game adapts itself to your style of play.", "Realistic, recognizable locations. Many of the locations are built from actual blueprints of real places set in a near future scenario.", "A game filled with people rather than monsters. This creates empathy with the game characters and enhances the realism of the game world.", "Rich character development systems: Skills, augmentations, weapon and item selections and multiple solutions to problems ensure that no two players will end the game with similar characters.", "Strong storyline: Built on \"real\" conspiracy theories, current events and expected advancements in technology. If it''s in the game, someone, somewhere believes it."]','["Cyberpunk,RPG,Stealth,Masterpiece,Classic,FPS,Sci-fi,Cult Classic,Action,Singleplayer,Dystopian,Inventory Management,Story Rich,Great Soundtrack,Immersive Sim,First-Person,Moddable,Atmospheric,Conspiracy,Action RPG"]','deus ex game of the year edition'),
	 (8592,'Deus Ex: Human Revolution - Director''s Cut (PS3) (UK)','Deus Ex: Human Revolution - Director''s Cut','https://store.steampowered.com/app/238010/Deus_Ex_Human_Revolution__Directors_Cut/','Action,RPG','["Video Games", "PlayStation 3", "Games"]','["Cyberpunk,Stealth,RPG,Sci-fi,FPS,Action,Story Rich,Singleplayer,Great Soundtrack,Transhumanism,Dystopian,First-Person,Masterpiece,Adventure,Atmospheric,Inventory Management,Shooter,Futuristic,Replay Value,Open World"]','deus ex human revolution directors cut'),
