INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (9388,'DOOM','DOOM','https://store.steampowered.com/app/379720/DOOM/','Action','["Video Games", "PC", "</span></span></span>", "Multiplayer On-line with modem.", "Will play on any computer & possibly and game console with a cd rom.", "Straight into the depths of Hell to shred the Demons that await.", "3-D Animated Graphics"]','["FPS,Gore,Action,Demons,Shooter,First-Person,Great Soundtrack,Multiplayer,Singleplayer,Fast-Paced,Sci-fi,Horror,Classic,Atmospheric,Difficult,Blood,Remake,Zombies,Co-op,Memes"]','doom'),
	 (9389,'DOOM [Online Game Code]','DOOM','https://store.steampowered.com/app/379720/DOOM/','Action','["Video Games", "PC", "</span></span></span>", "Youve come here for a reason. The Union Aerospace Corporations massive research facility on Mars is overwhelmed by fierce and powerful demons, and only one person stands between their world and ours. As the lone DOOM Marine, youve been activated to do one thing  kill them all.", "Expand your gameplay experience using DOOM SnapMap game editor to easily create, play, and share your content with the world.", "Developed by id software, the studio that pioneered the first-person shooter genre and created multiplayer Deathmatch, DOOM returns as a brutally fun and challenging modern-day shooter experience.", "Relentless demons, impossibly destructive guns, and fast, fluid movement provide the foundation for intense, first-person combat  whether youre obliterating demon hordes through the depths of Hell in the single-player campaign, or competing against your friends in numerous multiplayer modes."]','["FPS,Gore,Action,Demons,Shooter,First-Person,Great Soundtrack,Multiplayer,Singleplayer,Fast-Paced,Sci-fi,Horror,Classic,Atmospheric,Difficult,Blood,Remake,Zombies,Co-op,Memes"]','doom'),
	 (9390,'Doom 3','DOOM 3','https://store.steampowered.com/app/9050/DOOM_3/','Action','["Video Games", "PC", "Games", "</span></span></span>"]','["Horror,FPS,Action,Sci-fi,Dark,First-Person,Classic,Singleplayer,Shooter,Gore,Demons,Atmospheric,Zombies,Survival Horror,Mars,Futuristic,Moddable,Multiplayer,Masterpiece,Co-op"]','doom 3'),
