INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (11034,'Euro Truck Simulator','Euro Truck Simulator','https://store.steampowered.com/app/232010/Euro_Truck_Simulator/','Indie,Simulation','[]','["Simulation,Driving,Open World,Multiplayer,Singleplayer,Realistic,Relaxing,First-Person,Indie,TrackIR,Moddable,Adventure,Third Person,Exploration,Sandbox,Atmospheric,Management,Action,Online Co-Op,Survival"]','euro truck simulator'),
	 (11035,'Euro Truck Simulator 2 [Download]','Euro Truck Simulator 2','https://store.steampowered.com/app/227300/Euro_Truck_Simulator_2/','Indie,Simulation','["Video Games", "PC", "Games", "</span></span></span>", "Enjoy incredible scenery. Stunning visuals capture the majesty and charm of Europe in a map that stretches from the UK to Poland and down as far as northern Italy - with thousands of miles of road and hundreds of famous landmarks and structures.", "Get the real driving experience. Extremely detailed trucks, both inside and out, are based on real models. The cabs feature steering wheel support and working GPS to keep you on the road and help you reach your destination.", "Customize your ride. Choose from a wide selection of parts to enhance the performance or look of your fleet.", "Build your own business. Complete missions and gain cash to build garages, upgrades, drivers and more powerful vehicles. Explore the map and find new dealerships. Manage your money wisely to drive your way to the top."]','["Simulation,Driving,Open World,Realistic,Relaxing,Singleplayer,Moddable,Exploration,First-Person,Economy,Atmospheric,Adventure,Management,Indie,Casual,TrackIR,Racing,Sandbox,Action,RPG"]','euro truck simulator 2'),
	 (11036,'Euro Truck Simulator 2 - Austrian Paint Jobs Pack','Euro Truck Simulator 2 - Austrian Paint Jobs Pack','https://store.steampowered.com/app/461243/Euro_Truck_Simulator_2__Austrian_Paint_Jobs_Pack/','Indie,Simulation','[]','["Simulation,Indie"]','euro truck simulator 2 austrian paint jobs pack'),
