INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (11605,'Fallout 4 VR','Fallout 4 VR','https://store.steampowered.com/app/611660/Fallout_4_VR/','RPG','[]','["VR,Open World,Post-apocalyptic,RPG,Singleplayer,Shooter,Violent,Survival,Action,FPS,First-Person,Atmospheric,Adventure,Gore,Base Building,Great Soundtrack,Character Customization,Stealth,Multiplayer,Funny"]','fallout 4 vr'),
	 (11586,'Fallout 3','Fallout 3','https://store.steampowered.com/app/22300/Fallout_3/','RPG','["Video Games", "Xbox 360", "Games", "</span></span></span>", "Limitless Freedom! - Take in the sights and sounds of the vast Capital Wasteland! See the great monuments of the United States lying in post-apocalyptic ruin! You make the choices that define you and change the world. Just keep an eye on your Rad Meter!", "Experience S.P.E.C.I.A.L.! - Vault-Tec engineers bring you the latest in human ability simulation - the SPECIAL Character System! Utilizing new breakthroughs in points-based ability representation, SPECIAL affords unlimited customization of your character. Also included are dozens of unique skills and perks to choose from, each with a dazzling variety of effects!", "Fantastic New Views! - The wizards at Vault-Tec have done it again! No longer constrained to just one view, experience the world from 1st or 3rd person perspective. Customize your view with the touch of a button!", "The Power of Choice! - Feeling like a dastardly villain today, or a Good Samaritan? Pick a side or walk the line, as every situation can be dealt with in many different ways. Talk out your problems in a civilized fashion, or just flash your Plasma Rifle.", "Blast Em Away With V.A.T.S.! - Even the odds in combat with the Vault-Tec Assisted Targeting System for your Pip-Boy Model 3000! V.A.T.S. allows you to pause time in combat, target specific body parts on your target, queue up attacks, and let Vault-Tec take out your aggression for you. Rain death and destruction in an all-new cinematic presentation featuring gory dismemberments and spectacular explosions."]','["Open World,Post-apocalyptic,RPG,Singleplayer,Exploration,First-Person,Sci-fi,Action,Adventure,Moddable,Atmospheric,FPS,Shooter,Masterpiece,Third Person,Character Customization,Story Rich,Sandbox,Action RPG,Horror"]','fallout 3'),
	 (11587,'Fallout 3 [Online Game Code]','Fallout 3','https://store.steampowered.com/app/22300/Fallout_3/','RPG','["Video Games", "PC", "Games", "</span></span></span>", "Limitless Freedom! Take in the sights and sounds of the vast Capital Wasteland! See the great monuments of the United States lying in post-apocalyptic ruin! You make the choices that define you and change the world. Just keep an eye on your Rad Meter!", "Experience S.P.E.C.I.A.L.! Vault-Tec engineers bring you the latest in human ability simulation  the SPECIAL Character System! Utilizing new breakthroughs in points-based ability representation, SPECIAL affords unlimited customization of your character. Also included are dozens of unique ski"]','["Open World,Post-apocalyptic,RPG,Singleplayer,Exploration,First-Person,Sci-fi,Action,Adventure,Moddable,Atmospheric,FPS,Shooter,Masterpiece,Third Person,Character Customization,Story Rich,Sandbox,Action RPG,Horror"]','fallout 3'),
