INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (12899,'Final Fantasy IV','FINAL FANTASY IV','https://store.steampowered.com/app/312750/FINAL_FANTASY_IV/','RPG','["Video Games", "Retro Gaming & Microconsoles", "Game Boy Advance", "Games", "</span></span></span>", "Journey on land, on sea and in the air, exploring caves and mountains to recover stolen crystals", "Twelve different characters with new abilities, spells and items join and leave the party at different parts of the quest", "Explore 18 different towns and castles", "Collect dozens of magical spells and hundreds of weapons and items to help you on your quest", "All the astounding music, challenging adventures and interesting storyline that are the hallmarks of the Final Fantasy games"]','["JRPG,RPG,Fantasy,Remake,Story Rich,Classic,Great Soundtrack,Singleplayer,Turn-Based,Adventure,Turn-Based Combat,Masterpiece,1990''s,Anime,Difficult,Controller"]','final fantasy iv'),
	 (12900,'Final Fantasy IV','FINAL FANTASY IV','https://store.steampowered.com/app/312750/FINAL_FANTASY_IV/','RPG','["Video Games", "Kids & Family", "Nintendo DS", "Games", "</span></span></span>"]','["JRPG,RPG,Fantasy,Remake,Story Rich,Classic,Great Soundtrack,Singleplayer,Turn-Based,Adventure,Turn-Based Combat,Masterpiece,1990''s,Anime,Difficult,Controller"]','final fantasy iv'),
	 (12901,'Final Fantasy IV [Online Game Code]','FINAL FANTASY IV','https://store.steampowered.com/app/312750/FINAL_FANTASY_IV/','RPG','["Video Games", "PC", "Games", "</span></span></span>", "Fully voiced, dramatic cut-scenes", "Deep, emotionally charged character development", "All-new system for charting dungeons and uncovering the secrets within", "Inspiring score accessible at anytime from the built-in Jukebox"]','["JRPG,RPG,Fantasy,Remake,Story Rich,Classic,Great Soundtrack,Singleplayer,Turn-Based,Adventure,Turn-Based Combat,Masterpiece,1990''s,Anime,Difficult,Controller"]','final fantasy iv'),
	 (12902,'Final Fantasy IV : The After Years [Online Game Code]','FINAL FANTASY IV: THE AFTER YEARS','https://store.steampowered.com/app/346830/FINAL_FANTASY_IV_THE_AFTER_YEARS/','RPG','["Video Games", "PC", "Games", "</span></span></span>", "Ten Playable Tales - Begin your journey with \"Ceodore''s Tale.\" Complete it to unlock the tales of six additional characters, which can be played in any order, and then return to the core story with \"Kain''s Tale,\" \"The Lunarian''s Tale,\" and \"The Crystals.\"", "Active Time Battle - Take control of exhilarating combat made possible by the non-stop action in Square Enix''s iconic battle system.", "Lunar Phases - Feel the moon''s presence in combat, as its waxing and waning influences the potency of attacks and abilities of all combatants. Lunar phases cycle naturally with the passage of in-game time, or when resting at an inn, tent, or cottage.", "Band Abilities - Combine the strength of your party members to awesome effect with Band abilities that can be unlocked through in-game events or by levelling your characters'' Affinity.", "Minimap - Keep an eye on your current location and nearby surroundings, or click for quick access to the world map."]','["RPG,JRPG,Singleplayer,Fantasy,Anime,Turn-Based,Adventure,Story Rich,Classic"]','final fantasy iv the after years'),
	 (12903,'Final Fantasy IX','FINAL FANTASY IX','https://store.steampowered.com/app/377840/FINAL_FANTASY_IX/','RPG','["Video Games", "Retro Gaming &amp; Microconsoles", "PlayStation", "Games", "</span></span></span>"]','["JRPG,Great Soundtrack,Story Rich,Fantasy,Classic,RPG,Singleplayer,Turn-Based Combat,Adventure,Atmospheric,Turn-Based,Open World,Party-Based RPG,Funny,Masterpiece,Steampunk,Cult Classic,Anime,Exploration,Medieval"]','final fantasy ix'),
