	 (13639,'Freddi Fish 2: The Case of the Haunted Schoolhouse [Download]','Freddi Fish 2: The Case of the Haunted Schoolhouse','https://store.steampowered.com/app/294530/Freddi_Fish_2_The_Case_of_the_Haunted_Schoolhouse/','Adventure,Casual','["Video Games", "PC", "Games", "</span></span></span>", "Dive in as the underwater world changes with every new game start.", "Every location is filled with wonders, a simple click and who knows what will appear.", "New locations like sunken ships, submarines and the lost city of Atlantis.", "More then just an adventure title with mini-games like Crab Invaders, solve puzzles, draw pictures or join in on sing-a-longs."]','["Adventure,Casual,Family Friendly,Point & Click,Story Rich,Memes"]','freddi fish 2 the case of the haunted schoolhouse'),
	 (13640,'Freddi Fish 3: The Case of the Stolen Conch Shell','Freddi Fish 3: The Case of the Stolen Conch Shell','https://store.steampowered.com/app/294540/Freddi_Fish_3_The_Case_of_the_Stolen_Conch_Shell/','Adventure,Casual','[]','["Adventure,Casual,Point & Click,Family Friendly,Singleplayer,Education"]','freddi fish 3 the case of the stolen conch shell'),
	 (13641,'Freddi Fish 4: The Case of the Hogfish Rustlers of Briny Gulch [Download]','Freddi Fish 4: The Case of the Hogfish Rustlers of Briny Gulch','https://store.steampowered.com/app/294550/Freddi_Fish_4_The_Case_of_the_Hogfish_Rustlers_of_Briny_Gulch/','Adventure,Casual','["Video Games", "PC", "Games", "</span></span></span>", "Explore exciting Wild West locations, investigate captivating clues and meet adventurous new characters.", "Disguise Freddi and go undercover as a Rustler.", "Every location is filled with wonders, a touch and who knows what will appear, with over 500 secret click points theres a new surprise every time you play.", "Play Mini-games and activities like creating your own wanted poster."]','["Adventure,Casual,Point & Click,Family Friendly,Female Protagonist,Singleplayer"]','freddi fish 4 the case of the hogfish rustlers of briny gulch'),
	 (13642,'Freddi Fish 5: The Case of the Creature of Coral Cove [Download]','Freddi Fish 5: The Case of the Creature of Coral Cove','https://store.steampowered.com/app/294570/Freddi_Fish_5_The_Case_of_the_Creature_of_Coral_Cove/','Adventure,Casual','["Video Games", "PC", "Games", "</span></span></span>", "Explore the unopened Coral Cove Park, meet new characters and discover the mystery about the creature lurking inside.", "Many new puzzles and new challenges.", "Every location is filled with wonders, a touch and who knows what will appear, with over 500 secret click points theres a new surprise every time you play.", "Game changes every time you play creating a different experience each time."]','["Adventure,Casual,Family Friendly,Point & Click,Puzzle"]','freddi fish 5 the case of the creature of coral cove'),
	 (13643,'Freddi Fish and Luther''s Maze Madness','Freddi Fish and Luther''s Maze Madness','https://store.steampowered.com/app/284020/Freddi_Fish_and_Luthers_Maze_Madness/','Adventure,Casual','["Video Games", "PC", "Games", "</span></span></span>"]','["Casual,Adventure,Family Friendly,Puzzle,2D"]','freddi fish and luthers maze madness'),
	 (13644,'Freddi Fish and the Case of The Missing Kelp Seeds','Freddi Fish and the Case of the Missing Kelp Seeds','https://store.steampowered.com/app/283940/Freddi_Fish_and_the_Case_of_the_Missing_Kelp_Seeds/','Adventure,Casual','["Video Games", "PC", "Games", "</span></span></span>", "Like the real world, Freddi Fishs world changes every time you play.", "Discover fascinating places like King Crabs castle, a volcano or a sunken ship.", "Out of time? You can save the game and finish it later.", "Take breaks with Freddi Fish: play games like Feeding Time or uncover hundreds and hundreds of secret Click Points!"]','["Point & Click,Adventure,Family Friendly,Casual,Education,Singleplayer,Great Soundtrack,Classic"]','freddi fish and the case of the missing kelp seeds');
