INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (17157,'I am Setsuna [Online Game Code]','I am Setsuna','https://store.steampowered.com/app/441830/I_am_Setsuna/','RPG','["Video Games", "PC", "Games", "</span></span></span>", "Pre-order now to experience the beautiful music of I AM SETSUNA with an exclusive digital track ''The warmth of hope'' by composer Tomoki Miyoshi.", "A great homage to JRPG masterpieces of yesteryear, using the latest technology to develop a truly memorable story and player experience and bring the authentic JRPG style to current hardware.", "A new battle system inspired by the timeless JRPG classic, Chrono Trigger.", "An emotionally impactful and memorable story which immerses players in the narrative of Setsuna, whose story portrays heartrending sorrow.", "Beautiful character designs and varied in-game locales evoke nostalgia for classic RPGs"]','["JRPG,RPG,Turn-Based Combat,Great Soundtrack,Anime,Story Rich,Fantasy,Singleplayer,Atmospheric,Adventure,Open World"]','i am setsuna'),
	 (17158,'I am Setsuna Collector''s Edition','I am Setsuna Collector''s Edition','https://store.steampowered.com/bundle/962/I_am_Setsuna_Collectors_Edition/','RPG','[]','[]','i am setsuna collectors edition'),
