INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (20791,'Marimba VR','Marimba VR','https://store.steampowered.com/app/560930/Marimba_VR/','Casual,Indie,Simulation','[]','["Simulation,Indie,Casual,VR"]','marimba vr'),
	 (20792,'Marine Park Empire [Download]','Marine Park Empire','https://store.steampowered.com/app/294730/Marine_Park_Empire/','Casual,Simulation,Strategy','["Video Games", "PC", "Games", "</span></span></span>", "Immerse yourself in a fantastic 3D world filled with creatures from the uncharted waters of the sea. From Otters to Orcas, Octopus to Oarfish, Marine Park is overflowing with 28 unique species of marine animals big and small that you can add to your ultimate marine park.", "Go overboard in your marine park designs with over 150 structures, facilities and items to decorate your park and entertain your visitors with. Build wet-and-wild rides and unique attractions that your visitors can enjoy as they have a rip-roaring time in your marine park.", "Now land and marine animals go paw-in-flipper! Marine Park gives you a whopping 60 animals and over 450 unique building and decoration items to toy with as you build not only the best zoo or marine park, but a wildlife menagerie like no other!", "Embark on your own unique underwater quest by completing all 21 challenging scenarios, or experiment with the free-form game where you set the rules!"]','["Simulation,Casual,Strategy"]','marine park empire'),
	 (20793,'MarineVerse - VR Sailing Bundle','MarineVerse - VR Sailing Bundle','https://store.steampowered.com/bundle/5614/MarineVerse__VR_Sailing_Bundle/','Racing,Simulation,Sports,Casual','[]','[]','marineverse vr sailing bundle'),
