INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (21421,'Microsoft Flight Simulator X: Steam Edition (Boxed Steam Code)','Microsoft Flight Simulator X: Steam Edition','https://store.steampowered.com/app/314160/Microsoft_Flight_Simulator_X_Steam_Edition/','Simulation','["Video Games", "PC", "Games"]','["Flight,Simulation,Realistic,Open World,Multiplayer,Singleplayer,Moddable,Adventure,Atmospheric,First-Person,Action,Difficult,Massively Multiplayer,Co-op,Third Person,Strategy,Local Multiplayer,Military,Sandbox,VR"]','microsoft flight simulator x steam edition'),
	 (21422,'Microsoft Flight Simulator X: Steam Edition [Online Game Code]','Microsoft Flight Simulator X: Steam Edition','https://store.steampowered.com/app/314160/Microsoft_Flight_Simulator_X_Steam_Edition/','Simulation','["Video Games", "PC", "Games", "</span></span></span>", "Flying some of the world''s most iconic aircraft, Microsoft Flight Simulator X is equipped for every kind of flying adventure.", "Take the controls of aircraft such as the 747 jumbo jet, F/A-18 Hornet, P-51D Mustang, E H-101 helicopter and others and explore a world of aviation beauty that has entranced millions of plane fans from across the globe.", "The inclusion of AI-controlled jet ways, fuel trucks and moving baggage carts, adds extra realism to the experience of flying at busy airports.", "Whether you want to challenge your friends to a heart-pounding race or just take in the scenery, FSX Steam Edition will immerse you in a dynamic, living world that brings a realistic flying experience to you."]','["Flight,Simulation,Realistic,Open World,Multiplayer,Singleplayer,Moddable,Adventure,Atmospheric,First-Person,Action,Difficult,Massively Multiplayer,Co-op,Third Person,Strategy,Local Multiplayer,Military,Sandbox,VR"]','microsoft flight simulator x steam edition'),
	 (21423,'Microsoft FSX: Steam Edition + Fair Dinkum Flights Add-On Twin Pack','Microsoft FSX: Steam Edition + Fair Dinkum Flights Add-On Twin Pack','https://store.steampowered.com/bundle/3029/Microsoft_FSX_Steam_Edition__Fair_Dinkum_Flights_AddOn_Twin_Pack/','Simulation','[]','[]','microsoft fsx steam edition fair dinkum flights addon twin pack'),
