INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (25153,'PixelJunk Eden  [Online Game Code - Full Game]','PixelJunk™ Eden','https://store.steampowered.com/app/105800/PixelJunk_Eden/','Action,Casual,Indie','["Video Games", "PlayStation 3", "Digital Games & DLC", "Games", "</span></span></span>", "Stunning Visuals - Stylish graphics brought to life in gorgeous 1080p HD.", "Multiplayer Co-op - Local co-op play to for up to three players.", "Trophy and Online Support - Unlock Trophies and track high scores via online leaderboards.", "Video Recording - Record gameplay videos to the hard drive or upload directly to YouTube.", "Remote Play - Supports Remote Play for PSP system."]','["Casual,Indie,Platformer,Great Soundtrack,Atmospheric,Action,Music,Colorful,Singleplayer,Relaxing,2D,Addictive,Pixel Graphics"]','pixeljunk eden'),
	 (25154,'PixelJunk Eden [Online Game Code]','PixelJunk™ Eden','https://store.steampowered.com/app/105800/PixelJunk_Eden/','Action,Casual,Indie','["Video Games", "PC", "Games", "</span></span></span>"]','["Casual,Indie,Platformer,Great Soundtrack,Atmospheric,Action,Music,Colorful,Singleplayer,Relaxing,2D,Addictive,Pixel Graphics"]','pixeljunk eden'),
	 (25155,'PixelJunk™ Monsters 2','PixelJunk™ Monsters 2','https://store.steampowered.com/app/749800/PixelJunk_Monsters_2/','Action','[]','["Action,Tower Defense"]','pixeljunk monsters 2'),
	 (25156,'PixelJunk™ Monsters 2 Golden Outfits Pack','PixelJunk™ Monsters 2 Golden Outfits Pack','https://store.steampowered.com/app/854010/PixelJunk_Monsters_2_Golden_Outfits_Pack/','Action','[]','["Action"]','pixeljunk monsters 2 golden outfits pack'),
	 (25157,'PixelJunk Monsters Ultimate [Online Game Code]','PixelJunk™ Monsters Ultimate','https://store.steampowered.com/app/243780/PixelJunk_Monsters_Ultimate/','Strategy','["Video Games", "PC", "Games", "</span></span></span>", "Play four game modes: Single player campaign, local co-op play, online co-op, and a host of additional challenges", "Play Together: Local and online co-op will have you sharing your machine or playing with your friend over the net for a shared memorable experience. Online leaderboards show you how you stack up against your friends and everyone else in the world!", "Tikiman will travel across three distinct islands, spanning 47 unique environments to protect his offspring from monsters that attack by land and air. He will use every tower in his arsenal to protect them, with special power ups and more!", "There is also the mysterious Tum-Tum Island, that randomly generates levels for near infinite replayability; this amounts to literally hundreds of hours of gameplay, all set to an awesome soundtrack to keep you in the zone!", "We have also included unlockable content including concept art, music videos, sound tracks and more! For Steam we have created over 20 brand new achievements, giving the game 52 in total for you to unlock! Not to mention trading cards and badges!"]','["Tower Defense,Strategy,Local Co-Op,Online Co-Op,Co-op,2D,Indie,Singleplayer,Multiplayer"]','pixeljunk monsters ultimate'),
	 (25158,'PixelJunk™ Nom Nom Galaxy','PixelJunk™ Nom Nom Galaxy','https://store.steampowered.com/app/226100/PixelJunk_Nom_Nom_Galaxy/','Action,Casual,Indie,Strategy','[]','["Indie,Casual,Strategy,Action,Sandbox,Local Co-Op,Base Building,2D,Building,Platformer,Multiplayer,Local Multiplayer,Pixel Graphics,Co-op,Online Co-Op,Exploration,Survival,Early Access,Great Soundtrack,Metroidvania"]','pixeljunk nom nom galaxy'),
