INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (30728,'Sid Meier''s Civilization: Beyond Earth [Online Game Code]','Sid Meier''s Civilization®: Beyond Earth™','https://store.steampowered.com/app/65980/Sid_Meiers_Civilization_Beyond_Earth/','Strategy','["Video Games", "PC", "Games", "</span></span></span>"]','["Strategy,Turn-Based Strategy,Sci-fi,Space,4X,Turn-Based,Multiplayer,Singleplayer,Futuristic,Aliens,Tactical,Hex Grid,Grand Strategy,Replay Value,Exploration,Masterpiece,Atmospheric,Adventure,Moddable,Simulation"]','sid meiers civilization beyond earth'),
	 (30729,'Sid Meier''s Civilization: Beyond Earth [Online Game Code]','Sid Meier''s Civilization®: Beyond Earth™','https://store.steampowered.com/app/65980/Sid_Meiers_Civilization_Beyond_Earth/','Strategy','["Video Games", "Mac", "Games", "</span></span></span>", "Establish your cultural identity by choosing one of eight different expedition sponsors, each with its own leader and unique gameplay benefits.", "Explore the dangers and benefits of a new planet filled with dangerous terrain, mystical resources, and hostile life forms unlike those of Earth.", "To reflect progress forward into an uncertain future, technology advancement occurs through a series of nonlinear choices that affect the development of mankind.", "Build and deploy advanced military, economic and scientific satellites that provide strategic offensive, defensive and support capabilities from orbit.", "Unlock different upgrades through the tech web and customize your units to reflect your play style."]','["Strategy,Turn-Based Strategy,Sci-fi,Space,4X,Turn-Based,Multiplayer,Singleplayer,Futuristic,Aliens,Tactical,Hex Grid,Grand Strategy,Replay Value,Exploration,Masterpiece,Atmospheric,Adventure,Moddable,Simulation"]','sid meiers civilization beyond earth'),
	 (30730,'Sid Meier''s Civilization: Beyond Earth Exoplanets Map Pack','Sid Meier''s Civilization: Beyond Earth Exoplanets Map Pack','https://store.steampowered.com/app/304010/Sid_Meiers_Civilization_Beyond_Earth_Exoplanets_Map_Pack/','Strategy','[]','["Strategy"]','sid meiers civilization beyond earth exoplanets map pack'),
	 (30731,'Sid Meier''s Civilization: Beyond Earth - Rising Tide','Sid Meier''s Civilization: Beyond Earth - Rising Tide','https://store.steampowered.com/app/353830/Sid_Meiers_Civilization_Beyond_Earth__Rising_Tide/','Strategy','[]','["Strategy,Sci-fi,Turn-Based,4X,Turn-Based Strategy,Multiplayer,Space,Singleplayer"]','sid meiers civilization beyond earth rising tide'),
	 (30732,'Sid Meier''s Civilization III Complete','Sid Meier''s Civilization® III Complete','https://store.steampowered.com/app/3910/Sid_Meiers_Civilization_III_Complete/','Strategy','["Video Games", "PC", "Games", "</span></span></span>", "Build the ultimate empire in an epic quest to rule the world.", "This all-in-one collection of the original Civilization III and its two expansions is the perfect opportunity for Civ newcomers to experience the &#8220;greatest computer strategy game of all time.&#8221;", "Negotiate, trade, conquer, and rule the world. The addictive Sid Meier gameplay gives you many paths to victory by combining diplomatic finesse, cultural domination, and sheer military might.", "Enjoy the definitive Civ III experience. All rule changes, extra scenarios, rebalancing of units, special abilities, additional units, difficulty levels, incremental patches, and other game options wrapped up into one package.", "Includes all Conquest scenarios, multiplayer modes, and 31 playable nations.", "Build the ultimate empire in an epic quest to rule the world.", "This all-in-one collection of the original Civilization III and its two expansions is the perfect opportunity for Civ newcomers to experience the &#8220;greatest computer strategy game of all time.&#8221;"]','["Strategy,Turn-Based Strategy,Turn-Based,Classic,4X,Historical,Singleplayer,Replay Value,Multiplayer,Simulation,Military,Grand Strategy,Exploration,Masterpiece,Addictive,City Builder,Old School"]','sid meiers civilization iii complete'),
