INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (34686,'The Book of Unwritten Tales','The Book of Unwritten Tales','https://store.steampowered.com/app/215160/The_Book_of_Unwritten_Tales/','Adventure','["Video Games", "PC", "Games", "</span></span></span>"]','["Adventure,Point & Click,Fantasy,Comedy,Singleplayer,Puzzle,Funny,Story Rich,Great Soundtrack,Female Protagonist,Casual,Classic,Hidden Object"]','the book of unwritten tales'),
	 (34687,'The Book of Unwritten Tales [Download]','The Book of Unwritten Tales','https://store.steampowered.com/app/215160/The_Book_of_Unwritten_Tales/','Adventure','["Video Games", "PC", "Games", "</span></span></span>"]','["Adventure,Point & Click,Fantasy,Comedy,Singleplayer,Puzzle,Funny,Story Rich,Great Soundtrack,Female Protagonist,Casual,Classic,Hidden Object"]','the book of unwritten tales'),
	 (34688,'The Book of Unwritten Tales 2 [Online Game Code]','The Book of Unwritten Tales 2','https://store.steampowered.com/app/279940/The_Book_of_Unwritten_Tales_2/','Adventure','["Video Games", "PC", "Games", "</span></span></span>", "A new adventure from KING Art, the creators of The Book of Unwritten Tales, The Critter Chronicles and The Raven  Legacy of a Master Thief with a fantasy story with over 20 hours of pointing and clicking", "The trademark BoUT-humor, lovingly spoofing LotR, Game of Thrones, Harry Potter, Discworld, The Hobbit, WoW and more", "Hundreds of weird, yet oddly logical puzzles and the well-proven \"Multi-Character-Gameplay\"", "The established four playable characters Wilbur, Nate, Ivo and Critter and an ensemble of quirky characters, both well-established and brand-new", "Projection Mapping technology unites the merits of 2D and 3D styles and technique and an epic soundtrack with all the classics and many new compositions"]','["Adventure,Point & Click,Comedy,Fantasy,Singleplayer,Story Rich,Funny,Kickstarter,Great Soundtrack,Atmospheric,Puzzle"]','the book of unwritten tales 2'),
	 (34689,'The Book of Unwritten Tales 2 Almanac Edition Extras','The Book of Unwritten Tales 2 Almanac Edition Extras','https://store.steampowered.com/app/346230/The_Book_of_Unwritten_Tales_2_Almanac_Edition_Extras/','Adventure','[]','["Adventure"]','the book of unwritten tales 2 almanac edition extras'),
	 (34690,'The Book of Unwritten Tales Digital Extras','The Book of Unwritten Tales Digital Extras','https://store.steampowered.com/app/215200/The_Book_of_Unwritten_Tales_Digital_Extras/','Adventure','[]','["Adventure"]','the book of unwritten tales digital extras'),
	 (34691,'The Book of Unwritten Tales: The Critter Chronicles [Download]','The Book of Unwritten Tales: The Critter Chronicles','https://store.steampowered.com/app/221830/The_Book_of_Unwritten_Tales_The_Critter_Chronicles/','Adventure,Indie','["Video Games", "PC", "Games", "</span></span></span>"]','["Adventure,Point & Click,Fantasy,Indie,Comedy,Singleplayer,Funny"]','the book of unwritten tales the critter chronicles'),
	 (34692,'The Book of Unwritten Tales: The Critter Chronicles [Online Game Code]','The Book of Unwritten Tales: The Critter Chronicles','https://store.steampowered.com/app/221830/The_Book_of_Unwritten_Tales_The_Critter_Chronicles/','Adventure,Indie','["Video Games", "PC", "Games", "</span></span></span>", "Immerse yourself in the prequel to the most successful adventure of the year 2009!", "Play as both Nate and Critter: You and you alone decide with whom you want to spend more time."]','["Adventure,Point & Click,Fantasy,Indie,Comedy,Singleplayer,Funny"]','the book of unwritten tales the critter chronicles'),
	 (34693,'The Book of Unwritten Tales: The Critter Chronicles (Mac) [Online Game Code]','The Book of Unwritten Tales: The Critter Chronicles','https://store.steampowered.com/app/221830/The_Book_of_Unwritten_Tales_The_Critter_Chronicles/','Adventure,Indie','["Video Games", "Mac", "Games", "</span></span></span>", "You can download your game or software order an unlimited number of times for personal use.", "Please check the system requirements to verify this game works with your computer and/or operating system before purchase.", "You can also shop for digital games on your mobile device."]','["Adventure,Point & Click,Fantasy,Indie,Comedy,Singleplayer,Funny"]','the book of unwritten tales the critter chronicles'),
