INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (35018,'The Escapists [Online Game Code]','The Escapists','https://store.steampowered.com/app/298630/The_Escapists/','Action,Adventure,Indie,Simulation,Strategy','["Video Games", "PC", "Games", "</span></span></span>", "2 Fully operational prisons complete with routines to give you a flavour of how it *really* is inside!", "6 Separate job opportunities for you to sink your teeth into If you have the knowledge to earn and hold down these employment paths of course!", "100 + Unique Items for you to seek out and perhaps even craft useful items with. (Team17 fully endorse the use of various weapons such as shivs, nunchucks and maces  within a fictional setting of course!).", "Various Favour types for you to tackle offered up by inmates  You wouldnt want to go upsetting them now, would you?", "Multiple escape routes for you to work out and achieve the title of The Escapist!"]','["Pixel Graphics,Strategy,Crafting,Singleplayer,2D,Simulation,Indie,Difficult,Survival,Action,Adventure,Puzzle,RPG,Top-Down,Funny,Sandbox,Multiplayer,Comedy,Rogue-like,Co-op"]','the escapists'),
	 (35019,'The Escapists (PS4) (UK IMPORT)','The Escapists','https://store.steampowered.com/app/298630/The_Escapists/','Action,Adventure,Indie,Simulation,Strategy','["Video Games", "Kids & Family", "PlayStation 4", "Games", "</span></span></span>", "6 Fully operational prisons to give you a flavour of how it *really* is inside!", "10 Separate job opportunities for you to sink your teeth into", "Around 200 unique Items for you to seek out and perhaps even craft useful items with.", "Highly opinionated and incredibly funny inmates and guards to keep you on your toes", "Multiple escape routes for you to work out and achieve the title of ''The Escapist''!"]','["Pixel Graphics,Strategy,Crafting,Singleplayer,2D,Simulation,Indie,Difficult,Survival,Action,Adventure,Puzzle,RPG,Top-Down,Funny,Sandbox,Multiplayer,Comedy,Rogue-like,Co-op"]','the escapists'),
	 (35020,'The Escapists [Xbox One]','The Escapists','https://store.steampowered.com/app/298630/The_Escapists/','Action,Adventure,Indie,Simulation,Strategy','["Video Games", "Xbox One", "Games", "</span></span></span>", "6 Fully operational prisons to give you a flavour of how it *really* is inside!", "10 Separate job opportunities for you to sink your teeth into", "If you have the knowledge to earn and hold down employment paths of course!", "100 + Unique Items for you to seek out and perhaps even craft useful items with.", "Highly opinionated and incredibly funny inmates and guards to keep you on your toes"]','["Pixel Graphics,Strategy,Crafting,Singleplayer,2D,Simulation,Indie,Difficult,Survival,Action,Adventure,Puzzle,RPG,Top-Down,Funny,Sandbox,Multiplayer,Comedy,Rogue-like,Co-op"]','the escapists'),
	 (35021,'The Escapists [Online Game Code]','The Escapists','https://store.steampowered.com/app/298630/The_Escapists/','Action,Adventure,Indie,Simulation,Strategy','["Video Games", "PC", "Games", "</span></span></span>", "8 Fully operational prisons complete with routines to give you a flavour of how it *really* is inside!", "10 Separate job opportunities for you to sink your teeth into If you have the knowledge to earn and hold down these employment paths of course!", "185 + Unique Items for you to seek out and perhaps even craft useful items with. (Team17 fully endorse the use of various weapons such as shivs, nunchucks and maces  within a fictional setting of course!).", "Various Favour types for you to tackle offered up by inmates  You wouldnt want to go upsetting them now, would you?", "Prison Editor  Create from scratch your very own confinement masterpiece and share it with the community!"]','["Pixel Graphics,Strategy,Crafting,Singleplayer,2D,Simulation,Indie,Difficult,Survival,Action,Adventure,Puzzle,RPG,Top-Down,Funny,Sandbox,Multiplayer,Comedy,Rogue-like,Co-op"]','the escapists'),
