INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (36167,'The Typing of the Dead: Overkill [Download]','The Typing of The Dead: Overkill','https://store.steampowered.com/app/246580/The_Typing_of_The_Dead_Overkill/','Action','["Video Games", "PC", "Games", "</span></span></span>", "Randomised kill-words to make every game experience unique;", "Your keyboard is the weapon - type bullet holes into those zombie hordes!", "Three difficulty levels included to test your typing skills to the max as well as a special ''hardcore'' level for true keyboard warriors!", "Redefined HOTD gameplay to complement the new typing mechanics;", "Full Steam integration"]','["Typing,On-Rails Shooter,Zombies,Comedy,Action,Education,Parody,Arcade,Funny,Score Attack,Singleplayer,Horror,First-Person,Multiplayer,Shooter,Co-op,FPS,Great Soundtrack,Gore"]','the typing of the dead overkill'),
	 (36168,'The Typing of The Dead: Overkill Collection [Online Game Code]','The Typing of The Dead: Overkill Collection','https://store.steampowered.com/sub/48535/','Action','["Video Games", "PC", "Games", "</span></span></span>", "Typing of the dead: Overkill fuses the horror and comedy of the legendary House of the Dead series with unique typing mechanics in order to deliver a truly original gaming experience!", "This gruesome shooter puts you in the middle of a mutant outbreak in Bayou county. Blast pieces out of the zombie horde across 9 stages, one keystroke at a time, in order to save you and a friends life as you work to uncover the mystery behind the outbreak."]','[]','the typing of the dead overkill collection'),
	 (36169,'The Typing of the Dead: Overkill - Dancing with the Dead DLC','The Typing of the Dead: Overkill - Dancing with the Dead DLC','https://store.steampowered.com/app/286920/The_Typing_of_the_Dead_Overkill__Dancing_with_the_Dead_DLC/','Action','[]','["Action"]','the typing of the dead overkill dancing with the dead dlc'),
	 (36170,'The Typing of the Dead: Overkill - Love at First Bite DLC [Online Game Code]','The Typing of the Dead: Overkill - Love at First Bite DLC','https://store.steampowered.com/app/278131/The_Typing_of_the_Dead_Overkill__Love_at_First_Bite_DLC/','Action','["Video Games", "PC", "Games", "</span></span></span>", "Roses are red, violets are blue, mutants are ugly, so what do we do?", "Well, this time players will need to type increasingly more overblown and contrived sweet nothings in order to repel hordes of amorous mutants queuing up to give them a love bite theyll never forget."]','["Action,Typing,Zombies,Comedy,Horror,FPS"]','the typing of the dead overkill love at first bite dlc'),
	 (36171,'The Typing of The Dead: Overkill - Shakespeare DLC','The Typing of The Dead: Overkill - Shakespeare DLC','https://store.steampowered.com/app/259210/The_Typing_of_The_Dead_Overkill__Shakespeare_DLC/','Action','[]','["Action"]','the typing of the dead overkill shakespeare dlc'),
