INSERT INTO public.games (id,title,name,url,genre,categoria,tags,normalized_name) VALUES
	 (36398,'Thief Deadly Shadows [Download]','Thief: Deadly Shadows','https://store.steampowered.com/app/6980/Thief_Deadly_Shadows/','Action','["Video Games", "PC", "Games", "</span></span></span>", "Cutting-edge Action Stealth Gameplay - Hide in the shadows, sneak past the guards, or ambush them from the darkness!", "Huge Arsenal of Thieves'' Tools - Including lock picks, a blackjack, arrows, wall climbing gloves, oil flasks, flash bombs, and a dagger.", "An Entire City to Explore - Break into any building, mug nobles on the streets, spend your loot, and earn a reputation. Feel like a real thief in a cityscape of unparalleled responsiveness and interactivity.", "Advanced Artificial Intelligence - AI guards that see and hear, track evidence and suspiciousness, search for intruders, fight, give chase, and perform lip synching, facial expressions, and hundreds of lines of real-time dialog.", "Dynamic Lighting and Shadow System - Every character and object casts realistic, dynamic shadows that effect stealth gameplay."]','["Stealth,Atmospheric,Action,Steampunk,First-Person,Classic,Third Person,Dark,Story Rich,Horror,Singleplayer,Masterpiece,Fantasy,Adventure,Dark Fantasy,Immersive Sim,Medieval,Open World,RPG"]','thief deadly shadows'),
